import{_ as o}from"./chunks/7f063e65ae4c03f25024.CA8fKnFi.js";import{_ as a,C as l,o as r,c as n,j as e,a as i,E as s,a6 as c}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"如何开启一段全新的人生","description":"","frontmatter":{"title":"如何开启一段全新的人生","originalTitle":"How To Launch Into A Completely New Life","date":"2025-05-03","originalUrl":"https://thedankoe.com/letters/how-to-launch-into-a-completely-new-life/","minutes":9,"sourceHash":"8e51ce0c89045286873eea822eece95e0e00273e62e31b26892711b8d69b1c90","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-launch-into-a-completely-new-life/"}]]},"headers":[],"relativePath":"letters/how-to-launch-into-a-completely-new-life.md","filePath":"letters/how-to-launch-into-a-completely-new-life.md"}'),m={name:"letters/how-to-launch-into-a-completely-new-life.md"};function h(d,p,u,f,g,_){const t=l("ArticleMeta");return r(),n("div",null,[p[0]||(p[0]=e("h1",{id:"如何开启一段全新的人生",tabindex:"-1"},[i("如何开启一段全新的人生 "),e("a",{class:"header-anchor",href:"#如何开启一段全新的人生","aria-label":'Permalink to "如何开启一段全新的人生"'},"​")],-1)),s(t),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/VztPAofKWvg?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+o+'" alt=""></p><p>首先，你要明白，人生是以章节的形式展开的。</p><p>每一个章节都是4个阶段的可预测序列：</p><ul><li><strong>迷茫（Limbo）</strong> ——你不知道该做什么，也不知道自己想要什么。</li><li><strong>愿景（Vision）</strong> ——一个关于未来的图景开始形成，你开始在一条新的道路上行动，动力逐渐累积。</li><li><strong>心流（Flow）</strong> ——你无法把自己从正在追求的目标中拉出来。</li><li><strong>阻力（Resistance）</strong> ——指数级的进步不会永远持续，但你不想让它结束，往往因此伤害了自己。</li></ul><p>但大多数人都卡在了迷茫阶段。</p><p>你的一生都在被训练去遵循一个既定脚本。</p><p>你习惯了学校和工作带来的那种线性结果。</p><p>你习惯了让别人来给你确定感。</p><p>但当涉及到过一种非常规的生活时（因为那是获得非常规结果的唯一方式），你会把“感觉迷茫”解读为一种坏的信号。于是你弃船而逃，回到那个系统为你安排好的、只顾自身利益的舒适生活中去。</p><p>这也许正是你读这篇文章的原因。</p><p>你厌恶自己最终变得和其他人一样的想法。</p><p>但这意味着，你只能靠自己了。</p><p>你感觉自己像是迷失在一片茂密的森林里。透过树木你什么都<em>看</em>不到，所以你没意识到，5米之外就有一条通往山顶的路。</p><p>在这种情况下，你能做的最糟糕的事，就是什么都不做。</p><p>下面就是如何走出去的方法：</p><blockquote><p>顺便说一句，我做了一个<a href="https://app.kortex.co/public/document/b9063db2-418b-4876-ba20-45c354d33f0a" target="_blank" rel="noreferrer">把你的人生变成一场电子游戏的AI提示词</a>。你可以用它来指导自己实践这篇文章的内容（真的挺好用的）。</p></blockquote><h3 id="_1-如何收集愿景" tabindex="-1">1）如何收集愿景 <a class="header-anchor" href="#_1-如何收集愿景" aria-label="Permalink to &quot;1）如何收集愿景&quot;">​</a></h3><p>你的大脑是通过故事来理解世界的。</p><p>这就是你感觉迷茫的原因。</p><p>因为你不知道自己正在经历的是什么故事，或者你正在活出的，是别人分配给你的一个故事，而你能在灵魂深处感受到那种不契合。</p><p>重新掌控自己人生最难的部分，在于收集正确的拼图碎片，直到刚好形成足够的愿景，让你有足够的清晰度，能够自信地行动。</p><p>一开始，这幅拼图看起来就是一团乱麻。</p><p>你的大脑理不出个头绪。</p><p>你会感到压力和担忧，这导致思维变得狭窄而消极，让你极其难以注意到新的机会。</p><p>这就是你感觉被困住的原因。</p><p>所以，第一步是这样的：</p><p><em>允许自己让生活变得更糟。</em></p><p>没想到会是这样吧？</p><p>让我解释一下。</p><p>你感到迷茫、乏味、甚至没有生气，是因为你没有一个清晰的目标去努力实现。</p><p>但你并不知道自己想要什么。</p><p>由于你感觉迷茫、心思纷乱，一个“清晰的目标”是你的大脑最不可能想出来的东西，而你往往还会找各种理由，说明为什么那不是值得追求的正确目标。</p><p>问题是，目标不是孤立存在的。</p><p>一个强大而有明确目的的目标，恰恰是相反事物的结果：</p><p><em>一个你会拼尽全力去避免的负面结果——一旦你亲身经历过那个结果，你就会不惜一切避免再次经历它。</em></p><p>你需要一个要解决的问题。一个要攻击的敌人。而当你有了要去避免的东西时，你的目标就会在分量和清晰度上同时提升。</p><p>所以，那就是你应该把注意力转向的地方。</p><p>问问自己：“如果我一直这样下去，我的人生会走向哪里？”</p><p>带着这个念头静坐下来。</p><p>真正地、认真地静坐着去想它。</p><p>让它占据你的思绪，因为当它开始接管你的心智时，你的大脑就会渴望去学习、去实验、去成长。</p><h3 id="_2-如何改变你的心智" tabindex="-1">2）如何改变你的心智 <a class="header-anchor" href="#_2-如何改变你的心智" aria-label="Permalink to &quot;2）如何改变你的心智&quot;">​</a></h3><p>你现在的行为方式是这样，是因为你早已有了一个目标。</p><p>这就是心智的运作方式。</p><p>你的大脑是一台追求目标的机器，它以一种能够帮助自己收集有用信息、以实现该目标的方式来感知世界。</p><p>问题在于，你并没有意识到自己在追求的是什么目标，而这正在毁掉你的生活。</p><p>亚里士多德认为，一个情境的“终极因”，是它存在所指向的最终目的或终点目标。</p><p>在阿德勒心理学中，聚焦于目的论：我们不是被过去推动的，而是被目标拉动的。用乔丹·彼得森（Jordan Peterson）大概会说的话来讲：我们的行为方式，是朝着我们所指向的那个<em>目的</em>而有益的方式。</p><p>换句话说（这对很多人来说，会有点颠覆脑子）：</p><p>你处在目前的境况中，是因为你想要如此，只是这一点对你而言是无意识的，而且你一开始很可能根本不会相信这一点。</p><p>你感到迷茫、困惑或不堪重负，是因为这有助于实现一个目标——<em>避免因在人生中做出非常规的事而带来的痛苦、恐惧和羞耻感。</em></p><p>通过对你人生的负面结果获得完全的觉察，你已经为改变做好了心理上的准备。</p><p>现在，要彻底改变你的心智，你需要让自己沉浸在新的信息来源中，去发现那些能带来清晰度的拼图碎片。</p><p>读新的书。</p><p>和新的人交谈。</p><p>关注新的账号。</p><p>去一个你一直想去的地方。</p><p>去长时间散步，顺便听个播客。</p><p>学一门新技能的课程，以提升你的职业能力或开创一份事业。</p><p>或者，利用我上周发布的这个免费<a href="https://stan.store/thedankoe/p/mini-course-how-i-systemize-my-life-with-ai" target="_blank" rel="noreferrer">迷你课程</a>，把AI变成你的专注教练或战略顾问，这个课程讲的是我如何用AI来系统化管理我的生活。</p><p>你摄取的信息内容其实并不重要，只要它有潜力激发改变，就行。</p><p>当你的心智处于一种想要避免当前人生轨迹（那个新目标）的状态时，这正是真正学习发生的时刻。当你发现一个可以去追求的潜在机会时，你会感觉到多巴胺涌入大脑。</p><p>几周之内，你应该会对自己想要过的生活有一些想法了。</p><p>你有了一张地图，但接下来要面对的是真实的地域本身。</p><h3 id="_3-把你的人生游戏化" tabindex="-1">3）把你的人生游戏化 <a class="header-anchor" href="#_3-把你的人生游戏化" aria-label="Permalink to &quot;3）把你的人生游戏化&quot;">​</a></h3><p>你的心智是靠故事线运转的。</p><p>游戏是预先构建好的故事，带有某些机制，能收窄你的注意力，并让进步变得令人愉悦。</p><p>当你玩一款游戏时，其中会有：</p><ul><li>一个清晰的目标层级，让你知道该如何获胜</li><li>直接的反馈，让你知道自己是否在取得进步</li><li>规则，增添一种挑战感和技能发展的空间</li></ul><p>以上这些都是心流心理学的核心组成部分。</p><p>而心流，正是我们常常渴望（或对之上瘾）的那种最优体验状态。</p><p>社交媒体、游戏和娱乐公司，投入了成百上千亿美元，去构建能够利用这些机制的、最令人上瘾的信息。</p><p>然而，大多数人没有意识到的是，你可以在自己的人生中，复制出同样的效果。</p><p>不是获得那种进步和提升的幻觉，而是在这个过程中，真正成为一个全新的人。</p><p>下面是如何把你的人生游戏化的方法：</p><p><strong>1）设计这场游戏</strong></p><p>首先，要明白，大多数人对“目标”的定义都相当平庸。</p><p>目标是一种<em>方向</em>。</p><p>目标不是那种你必须不惜一切代价去实现的东西。</p><p>目标是一个用来做决策的透镜。目标本身<em>理应</em>随着你经验的增加而不断改变和演化。</p><p>大多数人会把下面这份清单当作“不管用”的东西而弃之不用，其原因仅仅是它本不该被视为一成不变的教条。</p><ul><li><strong>建立一个目标层级</strong>，由一个终极目标、若干长期目标和若干短期目标组成</li><li><strong>制定规则</strong>——为了朝终极目标推进，你不愿意在生活中牺牲什么？（健康、人际关系、长时间的工作等等）</li><li><strong>用可量化的优先任务作为反馈循环</strong>，比如每天写1000字、读10页书，或联系5个潜在客户</li></ul><p>当你正在活出的故事是模糊或无意识的时候，你的人生就会失去新奇感和模式识别所带来的那种活力。</p><p>当你创造出你的心智所渴求的秩序时，混乱就会容易得多地被挡在门外。</p><p><strong>2）创建一个新手教程阶段</strong></p><p>在一款游戏中，你是通过实际去玩来学习的，而不是靠研究无穷无尽的教程或观看别人玩游戏来学习。</p><p>你当然可以研究教程，但如果你甚至还没有开始玩这款游戏，那就不是在学习，而只是在娱乐。</p><p>当你在玩过游戏之后再去看教程时，你才能发现一些策略和战术，供你下次玩的时候去尝试。</p><p>开始玩这场游戏吧。</p><p>如果你还不能完全确定这是不是你想要一辈子去做的事，不必担心，因为你正是通过纠正错误来搞清楚自己到底想做什么的。你没法纠正一个根本不存在的错误。</p><p>一旦你开始真正“玩”起来（而且只有在你开始玩之后），才用以下两方面的知识来充实你的心智：</p><ul><li><strong>基本原理</strong>——大多数的成功，都不过是没有被这些基本原理分散注意力而已。</li><li><strong>具体的解决方案</strong>——当你凭自己的知识或直觉无法再取得进展时，有意识地去寻找一个答案。</li></ul><p>你每天最主要的优先任务，应该是每次1到2个小时的<em>学习和构建</em>。这些事情并非孤立发生。</p><p>对于那些还没有把AI融入生活的人来说，这可以说是AI最好的用途之一：帮你摆脱卡壳的状态。</p><p>如果我在用Photoshop做东西时卡住了，我可以直接让AI教我怎么完成下一步。</p><p>如果我连自己为什么卡住都不知道，我可以把整个情况的所有细节都告诉AI，让它帮我找出我的盲点。</p><p><strong>3）始终停留在“未知的边界”上</strong></p><p>在一些电子游戏中，你会有一张小地图。</p><p>你没探索过的地方是暗色的，探索过的地方则是可见的。</p><p>这在游戏中间接代表了两件事：你的经验和技能等级。</p><p>通常，那些暗色区域里，会有等级更高的怪物、任务和挑战。如果你以低等级的身份不知怎么闯到了那里，你要么会立刻被杀死，要么就得一直花时间逃命。那可一点都不好玩。</p><p>反过来说，如果你从不去探索那些暗色区域，你就会感到厌倦。同样，也不好玩。你已经把一切都做完了，你可以轻松杀掉怪物，也没有更多任务可以去做了。</p><p>在现实中，当你不知道该如何完成一项任务时，你会感到焦虑；而当你一直重复做同样的任务时，你又会感到厌倦。</p><p>要想一直停留在最优体验的区间内（也就是真正享受你的生活），你需要不断地培养自己的技能，并去接受更高的挑战。</p><p>那正是有意义的信息流被最大化的地方。</p><p>那正是你会感觉自己总是在学习新东西的地方。</p><p>那正是你的人生会变成一段令人愉悦、进步飞快、模糊一片的时光——一种清明感知的精神状态，一切都“感觉恰到好处”。那些黄金岁月。</p><p>这也是为什么一份朝九晚五的工作，是一块很好的垫脚石，但往往也是一份死刑判决。你学习、进步，直到卡在一遍又一遍重复同样的事情上。那不是一种有意义的生活方式。它会在心理上阉割你，并渐渐渗透进你生活的每一个方面。</p><p>很难就此给出具体建议，但如果非要我提一条的话：</p><p>每周或每月，稍微增加一点你所做事情的挑战难度。</p><p>这<em>并不</em>意味着增加更多的工作量。</p><p>而是意味着，把你所做的事，当作健身房里的举重训练来对待。</p><p>你不会一下子加50磅的重量。那些最有经验的举重者都知道，每一到两周只增加最小的2.5磅的杠铃片，才是他们看到最多进步、并一直保持这种“上瘾”状态的方式。</p><p>希望这篇文章对你有所帮助。</p><p>如果确实如此，请告诉我。</p><p>——丹</p><hr><p><a href="/en/letters/how-to-launch-into-a-completely-new-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',119))])}const A=a(m,[["render",h]]);export{k as __pageData,A as default};
